"""Telnet connection"""
# !/usr/bin/env python
# -*- coding: utf-8 -*-
from __future__ import absolute_import
from builtins import str
import os
import time
import telnetlib
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable, get_config_variable_from_string
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.remote_command_execute_and_verify import ExecuteAndVerify
from taf.ul.trs_e2e_fw.lib.utils.string_format import encode_str


logger = BackgroundLogger.Instance()


class TelnetConnection(ExecuteAndVerify):
    """
    Contains the methods which are used to connect switch via telnet connection.
    """

    def __init__(self, device, command_profile):
        """
        This method is used to create an object of telnet connection and initializes the class
        variables.
        Args:
            device: section name from the switch section of testline config.
            command_profile: section name from the switch section of testline config.

        Returns:

        """
        self.communicator = telnetlib.Telnet()
        self.ip = get_config_variable(['switch', device, "ip"])
        self.user = get_config_variable(['switch', device, "user"])
        self.password = get_config_variable(['switch', device, "password"])
        self.login_prompt = get_config_variable(['switch', device, "login_prompt"])
        self.enable_password = get_config_variable(["switch", device, "enable_password"])
        self.command_profile = get_config_variable_from_string(["switch", device, "command_profiles", command_profile])
        # self.command_profile = get_config_variable(["switch", device, "command_profiles", command_profile])
        self.enable_prompt = get_config_variable(["switch", device, "enable_prompt"])
        logger.info(self.command_profile)
        self.verification_timeout = get_config_variable(["switch", device, "verification_timeout"]) or 10
        self.error_messages = ["% Invalid input detected at '^' marker.", "% Incomplete command.",
                               "% Ambiguous command:",
                               "% Unknown command or computer name, or unable to find computer "
                               "address"]
        self.show_command = "show conf"

    def _perform_first_login_to_switch(self):
        """
        Logs in to the switch by taking appropriate credentials from config variable.
        Returns:

        """
        try:
            logger.info("logging into  switch  " + self.ip + " ....")
            self.communicator.open(host=self.ip)
            logger.info(self.communicator.read_until("User: ", timeout=self.verification_timeout))
            logger.info(self.communicator.write(encode_str(self.user) + "\n"))

            logger.info(self.communicator.read_until("Password:", timeout=self.verification_timeout))
            logger.info(self.communicator.write(encode_str(self.password) + "\n"))
            output = self.communicator.read_until(self.login_prompt, timeout=self.verification_timeout)
            logger.debug(output)
            logger.info("logged in successfully to " + self.ip)
        except Exception as err:
            BuiltIn().fail("Login to switch failed : " + str(err))

    def _perform_second_login_to_switch(self):
        """
        Enters en mode in Switch
        Returns:

        """
        # Do this second login when necessary
        self.communicator.write((encode_str("en") + '\r') + "\n")
        self.communicator.read_until("Password:", timeout=self.verification_timeout)
        self.communicator.write((encode_str(self.enable_password) + '\r') + "\n")
        # self.communicator.read_until(self.config_prompt,timeout=10)
        self.communicator.expect([self.enable_prompt], timeout=self.verification_timeout)

    def login_to_switch(self):
        """
        Performs following steps
        1) Login to switch
        2) Enter en mode on switch
        Returns:

        """
        try:
            logger.info("Logging to switch...")
            self._perform_first_login_to_switch()
            if not self.enable_password == "":
                self._perform_second_login_to_switch()
            # self._set_terminal_length()
            logger.info("Succesfully logged into Switch ({0})".format(self.ip))
        except Exception as error:
            BuiltIn().fail('Unable To Telnet Switch({0})\nError :: {1}'.format(self.ip, str(error)))

    def _execute_show_conf_command(self, prompt, dump_time="start"):
        """
        Executes show conf command on the switch
        Args:
            prompt:
            dump_time:

        Returns:

        """
        self.communicator.write(encode_str(self.show_command) + r"\n\r")
        output = self.communicator.read_until(prompt, self.verification_timeout)
        # id, obj, output = self.communicator.expect([prompt])
        logger.info("output of command {0} is {1}".format(self.show_command, output))
        dump_timestamp = time.strftime("%Y%m%d-%H%M%S")
        dest = 'execution_logs/show_command_{}_{}.txt'.format(dump_time, dump_timestamp)
        logger.info("dest filename for show command dump:", dest)
        if not os.path.exists(os.path.dirname(dest)):
            os.makedirs(os.path.dirname(dest))
        with open(dest, 'w') as f:
            f.write(output)

    def _set_terminal_length(self):
        self._execute_cmd("terminal length 0")

    def close_connection(self):
        """
        Close telenet session to switch.
        Returns:

        """
        logger.info("Closing telnet session with switch({0})".format(self.ip))
        self.communicator.close()

    def _execute_cmd(self, command, **kwargs):
        """
        Execute commands on telnet session.
        Args:
            command:

        Returns:

        """
        try:
            logger.info("command in execute telnet {}".format(command))
            self.communicator.write(command + "\r\n")
            id, obj, output = self.communicator.expect([self.enable_prompt])
            # output = self.communicator.read_until(self.config_prompt,timeout=50)
            logger.info("output of command {0} is {1}".format(command, output))
            return output
        except Exception:
            logger.error('command execution failed :: {0}'.format(command))

    def configure_switch(self, **kwargs):
        """Configure switch"""
        logger.info("Configuring Switch..")
        self.login_to_switch()
        self._execute_show_conf_command(self.enable_prompt)
        self.execute_commands_and_verify(**kwargs)
        self.close_connection()
